import { ChangeDetectionStrategy, Component, booleanAttribute, input, model } from '@angular/core';

export interface AevkoAccordionItem {
  id: string;
  label: string;
  content: string;
  disabled?: boolean;
}

@Component({
  selector: 'aevko-accordion',
  standalone: true,
  templateUrl: './accordion.component.html',
  styleUrl: './accordion.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { 'data-slot': 'accordion' },
})
export class AevkoAccordion {
  readonly items = input.required<readonly AevkoAccordionItem[]>();
  readonly type = input<'single' | 'multiple'>('single');
  readonly value = model<readonly string[]>([]);
  readonly collapsible = input(true, { transform: booleanAttribute });
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly id = input('aevko-accordion');
  readonly label = input('');
  readonly headingLevel = input<2 | 3 | 4 | 5 | 6>(2);

  protected expanded(item: AevkoAccordionItem): boolean {
    return this.value().includes(item.id);
  }
  protected toggle(item: AevkoAccordionItem): void {
    if (this.disabled() || item.disabled) return;
    const current = this.value();
    if (this.expanded(item)) {
      if (this.collapsible() || this.type() === 'multiple')
        this.value.set(current.filter((id) => id !== item.id));
      return;
    }
    this.value.set(this.type() === 'single' ? [item.id] : [...current, item.id]);
  }
}

:host {
  display: block;
}
section {
  border-bottom: 1px solid var(--aevko-border, #e4e4e7);
}
.heading {
  margin: 0;
}
button {
  align-items: center;
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
  display: flex;
  font: 500 0.875rem/1.5 var(--aevko-font-sans, sans-serif);
  justify-content: space-between;
  min-height: 3rem;
  padding: 1rem 0;
  gap: 1rem;
  text-align: start;
  width: 100%;
}
button:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.indicator {
  align-items: center;
  display: inline-flex;
  flex: none;
  transition: transform 200ms cubic-bezier(0.2, 0, 0, 1);
  color: var(--aevko-muted, #66666e);
}
.indicator.open {
  transform: rotate(180deg);
}
.indicator svg {
  height: 1rem;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
  width: 1rem;
}
[role='region'] {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  visibility: hidden;
  transition:
    grid-template-rows 220ms cubic-bezier(0.2, 0, 0, 1),
    opacity 180ms ease,
    visibility 0s 220ms;
}
[role='region'][data-state='open'] {
  grid-template-rows: 1fr;
  opacity: 1;
  visibility: visible;
  transition-delay: 0s;
}
.content-clip {
  min-height: 0;
  overflow: hidden;
}
button:hover:not(:disabled) > span:first-child {
  text-decoration: underline;
  text-underline-offset: 4px;
}
:host(.bordered) {
  border: 1px solid var(--aevko-border, #e4e4e7);
  padding-inline: 1rem;
}
:host(.bordered) section:last-child {
  border-bottom: 0;
}

p {
  font-size: 0.875rem;
  color: var(--aevko-muted, #66666e);
  line-height: 1.7;
  margin: 0;
  padding: 0 0 1rem;
}
@media (prefers-reduced-motion: reduce) {
  .indicator,
  [role='region'] {
    transition: none;
  }
}
